"""渔帆生鲜历史订单的费用汇总工具，与配货冻结无关。
只做已完结订单的金额统计。
"""



def order_fee_summary(orders: list) -> float:
    """对已完结订单求运费与包装费之和。"""
    return round(sum(o["fee"] for o in orders), 2)


def order_count_by_store(orders: list) -> dict:
    """按门店统计订单数。"""
    stats: dict = {}
    for o in orders:
        stats[o["store"]] = stats.get(o["store"], 0) + 1
    return stats
